from sqlalchemy import Column, Identity, Integer, String
from sqlmodel import Field, SQLModel


class Test(SQLModel, table=True):
    """对应表 `test`：id 为 GENERATED BY DEFAULT AS IDENTITY，text 为 VARCHAR(255)。"""

    __tablename__ = "test"

    id: int | None = Field(
        default=None,
        sa_column=Column(
            Integer,
            Identity(
                always=False,
                start=1,
                increment=1,
                minvalue=1,
                maxvalue=2147483647,
                cycle=False,
                cache=1,
            ),
            primary_key=True,
        ),
    )
    text: str | None = Field(default=None, sa_column=Column("text", String(255)))


class TestCreate(SQLModel):
    text: str | None = Field(default=None, max_length=255)


class TestUpdate(SQLModel):
    text: str | None = Field(default=None, max_length=255)
